import{At as e,Et as t,dt as n,ft as r,lt as i,n as a,ot as o,ut as s}from"./chunks/framework.8UxoGp64.js";var c=JSON.parse(`{"title":"ScrollArea 滚动区域","description":"","frontmatter":{},"headers":[],"relativePath":"components/scroll-area.md","filePath":"components/scroll-area.md","lastUpdated":1791177194000}`),l={name:`components/scroll-area.md`};function u(a,c,l,u,d,f){let p=e(`XhDemo`);return t(),i(`div`,null,[c[0]||=s(`<h1 id="scrollarea-滚动区域" tabindex="-1">ScrollArea 滚动区域 <a class="header-anchor" href="#scrollarea-滚动区域" aria-label="Permalink to “ScrollArea 滚动区域”">​</a></h1><p>提供带自定义滚动条的内容区域。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/scroll-area" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/scroll-area.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/scroll-area" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/scroll-area" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/scroll-area.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h2><p>创建纵向滚动区域</p>`,5),r(p,{src:`scroll-area/01-basic`}),c[1]||=s(`<h2 id="组件结构" tabindex="-1">组件结构 <a class="header-anchor" href="#组件结构" aria-label="Permalink to “组件结构”">​</a></h2><p>加粗的是必需部件。</p><p><code>data-scope=&quot;scroll-area&quot;</code>：<strong><code>root</code></strong> · <strong><code>viewport</code></strong> · <strong><code>content</code></strong> · <code>scrollbar</code></p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><h3 id="双轴滚动" tabindex="-1">双轴滚动 <a class="header-anchor" href="#双轴滚动" aria-label="Permalink to “双轴滚动”">​</a></h3><p>同时显示横向和纵向滚动条</p>`,6),r(p,{src:`scroll-area/02-both-axes`}),c[2]||=o(`h3`,{id:`横向滚动`,tabindex:`-1`},[n(`横向滚动 `),o(`a`,{class:`header-anchor`,href:`#横向滚动`,"aria-label":`Permalink to “横向滚动”`},`​`)],-1),c[3]||=o(`p`,null,`只启用横向滚动`,-1),r(p,{src:`scroll-area/03-orientation`}),c[4]||=o(`h3`,{id:`边缘渐隐`,tabindex:`-1`},[n(`边缘渐隐 `),o(`a`,{class:`header-anchor`,href:`#边缘渐隐`,"aria-label":`Permalink to “边缘渐隐”`},`​`)],-1),c[5]||=o(`p`,null,`提示还有更多内容`,-1),r(p,{src:`scroll-area/04-fade`}),c[6]||=o(`h3`,{id:`命令式滚动与到底通知`,tabindex:`-1`},[n(`命令式滚动与到底通知 `),o(`a`,{class:`header-anchor`,href:`#命令式滚动与到底通知`,"aria-label":`Permalink to “命令式滚动与到底通知”`},`​`)],-1),c[7]||=o(`p`,null,`scrollTo 滚动视口，reach-end 在滚到底那一下通知一次，常用来提示或续载`,-1),r(p,{src:`scroll-area/05-scroll-to`}),c[8]||=s(`<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to “设计指引”">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to “何时使用”">​</a></h3><ul><li>统一不同平台的滚动区域样式。</li><li>控制滚动条的方向和显示时机。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to “何时不用”">​</a></h3><ul><li>整页滚动交给浏览器。</li><li>大量列表数据使用<a href="./virtualizer">虚拟滚动</a>。</li><li>滚动加载使用<a href="./infinite-scroll">无限滚动</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to “特性”">​</a></h3><ul><li>支持横向、纵向和双轴滚动。</li><li>支持五种滚动条显示时机。</li><li><code>fade</code> 变体在可滚动边缘显示渐隐提示。</li><li>触屏设备默认保留原生滚动体验。</li><li><code>scrollTo</code> 滚动视口，参数与原生 <code>Element.scrollTo</code> 的对象形式同形；<code>smooth</code> 在减弱动效下即刻到位。Vue 从组件实例与默认插槽取，React 从函数式 children 取，Web Components 直接调元素的 <code>scrollTo</code>。</li><li><code>scroll-change</code> 按轴报滚动量，<code>reach-end</code> 在某条轴跨过末端那一下报一次；两者都不与原生 <code>scroll</code> 同名，不会冒泡进祖先的滚动监听。</li></ul><h3 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to “组合”">​</a></h3><ul><li>可用于<a href="./splitter">分栏</a>、<a href="./dialog">对话框</a>、<a href="./menu">菜单</a>和<a href="./table">表格</a>。</li></ul><h3 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h3><ul><li>根节点应设置明确高度。</li><li>内容可滚动时提供渐隐边缘或可见滚动条提示。</li></ul><h3 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to “反模式”">​</a></h3><ul><li>不要让内容决定滚动区域高度。</li><li>不要嵌套过多滚动区域。</li></ul><h2 id="api-参考" tabindex="-1">API 参考 <a class="header-anchor" href="#api-参考" aria-label="Permalink to “API 参考”">​</a></h2><h3 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to “产物”">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-scroll-area&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhScrollAreaContent</code> <code>XhScrollAreaCorner</code> <code>XhScrollAreaRoot</code> <code>XhScrollAreaScrollbar</code> <code>XhScrollAreaThumb</code> <code>XhScrollAreaTrack</code> <code>XhScrollAreaViewport</code></td></tr><tr><td>组合式函数</td><td><code>useScrollArea</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/scroll-area.css</code></td></tr></tbody></table><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to “Props”">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>排版方向，默认随文档。只影响横轴：RTL 下滚动量的正负、指针位移的方向都要翻转。 必须显式提供：组件不读取计算样式，无法感知从 RTL 祖先继承的方向。</td></tr><tr><td><code>forceVisible</code></td><td><code>boolean</code></td><td></td><td>触屏（粗指针）上也绘制自绘滚动条，默认 false：默认交给原生滚动。</td></tr><tr><td><code>hideDelay</code></td><td><code>number</code></td><td></td><td>收起前的等待毫秒（type 为 scroll / hover / scroll-hover 时生效），默认 600。</td></tr><tr><td><code>onReachEnd</code></td><td><code>(details: ScrollAreaScrollDetails) =&gt; void</code></td><td></td><td>某条轴滚到了末端：只在跨过末端那一下通知，停在末端不重复；内容不溢出时不通知。</td></tr><tr><td><code>onScrollChange</code></td><td><code>(details: ScrollAreaScrollDetails) =&gt; void</code></td><td></td><td>某条轴的滚动量变了（滚轮、键盘、拖动与命令式滚动都算），按轴分别通知。</td></tr><tr><td><code>orientation</code></td><td><code>ScrollAreaOrientation</code></td><td></td><td>归本组件管理的轴，默认 both。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg，影响滚动条厚度，也是边缘渐隐的带宽。</td></tr><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td><td>滚动条显示的时机，默认 scroll-hover。</td></tr><tr><td><code>variant</code></td><td><code>ScrollAreaVariant</code></td><td></td><td>形态：plain / fade，默认 plain。</td></tr></tbody></table><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to “事件”">​</a></h3><p>自定义元素将载荷放在 <code>detail</code>；Vue 使用同名 emit。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>scroll-change</code></td><td><code>ScrollAreaScrollDetails</code></td><td>某条轴的滚动量变了，按轴分别派发；detail 为 <code>{ orientation, offset, max }</code></td></tr><tr><td><code>reach-end</code></td><td><code>ScrollAreaScrollDetails</code></td><td>某条轴滚到了末端，只在跨过末端那一下派发；detail 为 <code>{ orientation, offset, max }</code></td></tr></tbody></table><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to “插槽”">​</a></h3><p>仅列出带载荷的插槽。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhScrollAreaRoot</code></td><td><code>default</code></td><td><code>ScrollAreaRootSlotProps</code></td><td></td></tr></tbody></table><h3 id="react-适配器-props" tabindex="-1">React 适配器 props <a class="header-anchor" href="#react-适配器-props" aria-label="Permalink to “React 适配器 props”">​</a></h3><p>只列各组件自己声明的那些：继承自 <code>ComponentPropsWithRef</code> 的 DOM 属性不在其中，根组件上与上面 Props 表同名的也不重复列。Vue 的对应物是上面的插槽表。</p><table tabindex="0"><thead><tr><th>React 组件</th><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>XhScrollAreaRoot</code></td><td><code>children</code></td><td><code>SlotChildren&lt;ScrollAreaRootSlotProps&gt;</code></td><td></td><td></td></tr><tr><td><code>XhScrollAreaScrollbar</code></td><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>该滚动条管理哪条轴。</td></tr></tbody></table><h3 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to “状态”">​</a></h3><p>公开状态写入 <code>data-state</code>。</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>scrollbar</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>corner</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h3 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to “connect API”">​</a></h3><p><code>getXxxProps()</code> 返回对应部件的宿主属性。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>type</code></td><td><code>ScrollbarType</code></td><td></td></tr><tr><td><code>orientation</code></td><td><code>ScrollAreaOrientation</code></td><td></td></tr><tr><td><code>vertical</code></td><td><code>ScrollAreaAxisState</code></td><td></td></tr><tr><td><code>horizontal</code></td><td><code>ScrollAreaAxisState</code></td><td></td></tr><tr><td><code>draggingAxis</code></td><td><code>Orientation | null</code></td><td>正被拖动的轴；未拖动时为 null。</td></tr><tr><td><code>cornerVisible</code></td><td><code>boolean</code></td><td>右下角补丁是否应显示：两条滚动条同时在场才有它的位置。</td></tr><tr><td><code>scrollTo</code></td><td><code>(options: ScrollAreaScrollToOptions) =&gt; void</code></td><td>滚动视口，与原生 Element.scrollTo 的对象形式同形；视口还没挂上时什么也不做。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getViewportProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getScrollbarProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td>某条轴的滚动条挂载点，同时充当该 scrollbar 的根节点。</td></tr><tr><td><code>getTrackProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getThumbProps</code></td><td><code>(props: ScrollAreaScrollbarProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCornerProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td>交叉口补丁，写在竖条的挂载点中；只有两条都在场时才显示。</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to “无障碍”">​</a></h2><h3 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to “键盘”">​</a></h3><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>焦点走到滚动区</td><td>视口带 tabindex=0，键盘用户能停在滚动区上；组件只在这一处动过 Tab 序列</td></tr><tr><td><code>PageUp</code> / <code>PageDown</code></td><td>focus in viewport</td><td>按视口高度翻页滚动；组件不监听、不拦截</td></tr><tr><td><code>ArrowUp</code> / <code>ArrowDown</code> / <code>ArrowLeft</code> / <code>ArrowRight</code></td><td>focus in viewport</td><td>逐行/逐列滚动；组件不监听、不拦截</td></tr><tr><td><code>Home</code> / <code>End</code></td><td>focus in viewport</td><td>滚到内容两端；组件不监听、不拦截</td></tr><tr><td><code>Space</code> / <code>Shift+Space</code></td><td>focus in viewport</td><td>整屏翻页；组件不监听、不拦截</td></tr></tbody></table><h3 id="aria" tabindex="-1">ARIA <a class="header-anchor" href="#aria" aria-label="Permalink to “ARIA”">​</a></h3><p>以下属性由 <code>connect</code> 生成。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>scrollbar</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><h2 id="样式参考" tabindex="-1">样式参考 <a class="header-anchor" href="#样式参考" aria-label="Permalink to “样式参考”">​</a></h2><h3 id="皮肤" tabindex="-1">皮肤 <a class="header-anchor" href="#皮肤" aria-label="Permalink to “皮肤”">​</a></h3><p><code>@xihan-ui/styles/scroll-area.css</code> 按 <code>[data-scope=&quot;scroll-area&quot;][data-part=&quot;root&quot;]</code> 部件选择器书写，发布产物以挂载类 <code>.xh-scope-scroll-area</code> 代替其中的 data-scope（特异性相同），位于 <code>xihan.components</code> 层。覆盖样式使用 <code>xihan.overrides</code>，部件选择器照常可用。</p><h3 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to “数据属性”">​</a></h3><p>由 <code>connect</code> 生成；条件不成立时不输出无值属性。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>root</code></td><td><code>data-reveal-mode</code></td><td>props.type</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>viewport</code></td><td><code>data-at-max-horizontal</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-at-max-vertical</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-at-min-horizontal</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-at-min-vertical</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-lane-horizontal</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-lane-vertical</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>viewport</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>viewport</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>viewport</code></td><td><code>data-variant</code></td><td>props.variant</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>scrollbar</code></td><td><code>data-dragging</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-gutter</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-native</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-orientation</code></td><td>axis</td></tr><tr><td><code>scrollbar</code></td><td><code>data-reveal-mode</code></td><td>props.type</td></tr><tr><td><code>scrollbar</code></td><td><code>data-scrolling</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>scrollbar</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>scrollbar</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr><tr><td><code>corner</code></td><td><code>data-state</code></td><td>&#39;visible&#39; | &#39;hidden&#39;</td></tr></tbody></table><h3 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to “CSS 变量”">​</a></h3><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；默认来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>默认来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-scroll-area-fade-size</code></td><td><code>viewport</code></td><td><code>-webkit-mask-image</code><br><code>mask-image</code></td><td><code>at-max-horizontal</code><br><code>at-max-vertical</code><br><code>at-min-horizontal</code><br><code>at-min-vertical</code><br><code>not([data-at-max-horizontal])</code><br><code>not([data-at-max-vertical])</code><br><code>not([data-at-min-horizontal])</code><br><code>not([data-at-min-vertical])</code><br><code>size=lg</code><br><code>size=sm</code><br><code>variant=fade</code></td><td><code>--xh-space-4</code><br><code>--xh-space-6</code><br><code>--xh-space-8</code></td><td>scroll-area 的 viewport 部件 -webkit-mask-image、mask-image 覆盖槽。</td></tr></tbody></table><h3 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to “动效”">​</a></h3><p>动效角色：状态 · 出现（见<a href="./../design/motion#角色">动效规范</a>）。</p><p><code>opacity</code> · <code>visibility</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h3 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to “RTL”">​</a></h3><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像；另有按 <code>dir</code> 分支的规则。</p>`,55)])}var d=a(l,[[`render`,u]]);export{c as __pageData,d as default};